interface.definition:
if(
  ri!isReadOnly,
  /*READ ONLY*/
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Anticipated Start Date",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"anticipatedStartDate", tostring(null)))
                      )
                    )
                  ),
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Anticipated End Date",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"anticipatedEndDate", tostring(null)))
                      )
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Primary Industry",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"industry", tostring(null)))
                      )
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "US CPA License",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: if(
                          property(ri!nominationView,"hasCpaLicense", toboolean(null)),
                          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934655",
                          if(
                            property(ri!nominationView,"hasCpaLicense", toboolean(null))=false,
                            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934661",
                            #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378"
                          )
                        )
                      )
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "States",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"statesForCpaLicence", tostring(null)))
                      )
                    )
                  )
                }
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Is the candidate proficient in other languages besides English?",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: if(
                          property(ri!nominationView,"isOtherLanguage", toboolean(null)),
                          #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934655",
                          if(
                            property(ri!nominationView,"isOtherLanguage", toboolean(null))=false,
                            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934661",
                            #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378"
                          )
                        )
                      )
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Languages",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"languageOtherThanEng", tostring(null)))
                      )
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_richTextDisplayField"(
                label: "Group/Role Considerations",
                value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"roleConsideration", tostring(null)))
                )
              )
            }
          )
        },
        showDividers: true()
      )
    },
    marginBelow: "STANDARD"
  ),
  /*FORM LAYOUT*/
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        showDividers: true,
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_dateField"(
                      label: "Anticipated Start Date *",
                      value: ri!nomination.anticipatedStartDate,
                      saveInto: ri!nomination.anticipatedStartDate,
                      required: true,
                      validations: if(
                        ri!nomination.anticipatedStartDate < today(),
                        "Start date cannot be earlier than today.",
                        null
                      ),
                      validationGroup: "main"
                    )

                  ),
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_dateField"(
                      label: "Anticipated End Date *",
                      value: ri!nomination.anticipatedEndDate,
                      saveInto: ri!nomination.anticipatedEndDate,
                      required: true,
                      validations: if(
                        ri!nomination.anticipatedEndDate < today(),
                        "End date cannot be earlier than today.",
                        if(
                          ri!nomination.anticipatedEndDate <= ri!nomination.anticipatedStartDate,
                          "End date must be after start date",
                          null
                        )
                      ),
                      validationGroup: "main"
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Primary Industry *",
                placeholder: "--Select--",
                choiceLabels: property(ri!industries,"industry",null),
                choiceValues: property(ri!industries,"industryId",null),
                value: ri!nomination.primaryIndustryId,
                saveInto: ri!nomination.primaryIndustryId,
                required: true,
                validationGroup: "main"
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Primary Industry - Other",
                labelPosition: "ABOVE",
                value: index(ri!nomination, "primaryIndustryOther", {}),
                saveInto: {
                  ri!nomination.primaryIndustryOther
                },
                characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                disabled:  ri!nomination.primaryIndustryId <> #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4149854",
                required: ri!nomination.primaryIndustryId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4149854"
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Group/Role Considerations",
                value:property(ri!nomination,"roleConsideration",null),
                saveInto: ri!nomination.roleConsideration,
                characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_radioButtonField"(
                label: "US CPA License *",
                helpTooltip: "Does the candidate hold any active US CPA license(s) or previously held a US CPA license? If yes, please specify which state(s).",
                choiceLabels: {"Yes","No"},
                choiceValues: {true,false},
                value: property(ri!nomination,"hasCpaLicense",null),
                saveInto: {
                  ri!nomination.hasCpaLicense,
                  if(
                    or(
                      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!nomination,"hasCpaLicense",null)),
                      toboolean(property(ri!nomination,"hasCpaLicense",null)) = false
                    ),
                    a!save(
                      ri!nomination.statesForCpaLicence,
                      null
                    ),
                    null
                  )
                },
                required: true,
                choiceLayout: "COMPACT",
                validationGroup: "main"
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: if(
                  property(ri!nomination,"hasCpaLicense",null) = true,
                  "States *",
                  "States"
                ),
                value: property(ri!nomination,"statesForCpaLicence",null),
                saveInto: {
                  ri!nomination.statesForCpaLicence
                },
                characterLimit:#"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                required: property(ri!nomination,"hasCpaLicense",null) = true,
                disabled: or(
                  property(ri!nomination,"hasCpaLicense",null) = false,
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!nomination,"hasCpaLicense",null))
                ),
                validationGroup: "main"
              ),
              #"SYSTEM_SYSRULES_radioButtonField"(
                label: "Is the candidate proficient in other languages besides English? If yes, please specify what language(s). *",
                choiceLabels: {"Yes","No"},
                choiceValues: {true,false},
                value: property(ri!nomination,"isOtherLanguage",null),
                saveInto: {
                  ri!nomination.isOtherLanguage,
                  if(
                    or(
                      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!nomination,"isOtherLanguage",null)),
                      toboolean(property(ri!nomination,"isOtherLanguage",null)) = false
                    ),
                    a!save(
                      ri!nomination.languageOtherThanEng,
                      null
                    ),
                    null
                  )
                },
                required: true,
                choiceLayout: "COMPACT",
                validationGroup: "main"
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Languages",
                value:property(ri!nomination,"languageOtherThanEng",null),
                saveInto: ri!nomination.languageOtherThanEng,
                characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                required:toboolean(property(ri!nomination,"isOtherLanguage",null)) = true,
                disabled:or(
                  toboolean(property(ri!nomination,"isOtherLanguage",null)) = false,
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!nomination,"isOtherLanguage",null))
                )
              )
            }
          )
        }
      )
    },
    marginBelow: "STANDARD"
  )
)
